// Source of the CloudFront Function (runtime cloudfront-js-2.0, viewer-request)
// that redirects the alias hosts to the apex domain (SPEC-DOMINIO 6.3.2). It is
// generated, not hand-written in the stack, so the exact text the tests execute
// in a VM is the text CloudFormation deploys.

export const WWW_REDIRECT_CACHE_CONTROL = 'max-age=3600';

export interface WwwRedirectFunctionInput {
  readonly apexDomain: string;
  readonly redirectDomains: readonly string[];
  // Responses generated by a viewer-request function never reach the origin, so
  // the response headers policy does not apply to them; HSTS must be set here.
  readonly strictTransportSecurity: string;
}

export function wwwRedirectFunctionCode(input: WwwRedirectFunctionInput): string {
  const { apexDomain, redirectDomains, strictTransportSecurity } = input;
  // JSON.stringify yields valid JS string literals; the config schema already
  // restricts hostnames to lower-case LDH labels.
  return `var APEX = ${JSON.stringify(apexDomain)};
var REDIRECT_HOSTS = ${JSON.stringify(redirectDomains)};
var STRICT_TRANSPORT_SECURITY = ${JSON.stringify(strictTransportSecurity)};
var CACHE_CONTROL = ${JSON.stringify(WWW_REDIRECT_CACHE_CONTROL)};

// request.querystring is parsed but not decoded: values are re-joined exactly as
// the client sent them. Order is kept per key (multiValue groups repeated keys
// in client order), not globally across interleaved keys. A key without a value is emitted bare (no "=").
function buildQuery(querystring) {
  var parts = [];
  Object.keys(querystring).forEach(function (key) {
    var entry = querystring[key];
    var values = entry.multiValue ? entry.multiValue : [entry];
    values.forEach(function (item) {
      parts.push(item.value === '' ? key : key + '=' + item.value);
    });
  });
  return parts.length === 0 ? '' : '?' + parts.join('&');
}

function handler(event) {
  var request = event.request;
  var hostHeader = request.headers.host;
  var host = hostHeader ? hostHeader.value.toLowerCase() : '';
  if (REDIRECT_HOSTS.indexOf(host) === -1) {
    return request;
  }
  return {
    statusCode: 301,
    statusDescription: 'Moved Permanently',
    headers: {
      location: { value: 'https://' + APEX + request.uri + buildQuery(request.querystring) },
      'strict-transport-security': { value: STRICT_TRANSPORT_SECURITY },
      'cache-control': { value: CACHE_CONTROL },
    },
  };
}
`;
}
